inputs={'commit': 'dfb183ddf35a7116ef118d1d2e1e5b49dcbb21c7', 'sha256': '7b13a4cb6ac126a9c3c972ab66c8458be2af3c6bf9191df132707c11f4415ca1', 'bytes': 24416, 'payload': ''}
import pathlib,json,hashlib,base64,zlib,fcntl,os,time
root=pathlib.Path('/data/user/jxu957/experiments/dynrpo-qwen25-7b-probe-warmup-20261019/algorithm-improvement-20261021/hard-enrichment-20261021')
root.mkdir(parents=True,exist_ok=True)
with (root/'prepare.lock').open('a') as lock:
 fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
 code=root/('code-'+inputs['commit'][:12]);code.mkdir(exist_ok=True)
 raw=zlib.decompress(base64.b64decode(inputs['payload']));assert len(raw)==inputs['bytes'] and hashlib.sha256(raw).hexdigest()==inputs['sha256']
 p=code/'hard_enrichment.py'
 if p.exists():assert p.read_bytes()==raw,'Immutable source differs'
 else:
  with p.open('xb') as f:f.write(raw);f.flush();os.fsync(f.fileno())
 publication=dict(commit=inputs['commit'],code_root=str(code),files={'hard_enrichment.py':dict(path=str(p),bytes=len(raw),sha256=inputs['sha256'])},GPU_used=False)
 p=root/'source-publication.json';value=json.dumps(publication,sort_keys=True,separators=(',',':')).encode()+b'\n'
 if p.exists():assert p.read_bytes()==value,'Existing isolated source publication differs'
 else:
  with p.open('xb') as f:f.write(value);f.flush();os.fsync(f.fileno())
 print(json.dumps(dict(status='PUBLISHED_CPU_HARD_ENRICHMENT_SOURCE_STAGED',source=publication,epoch=time.time())))
